INSERT INTO `creature_template` (`entry`, `name`, `subname`, `IconName`, `minlevel`, `maxlevel`, `faction`, `npcflag`, `unit_class`, `unit_flags`, `type`, `flags_extra`, `HealthModifier`, `ScriptName`) VALUES
(9100001, 'Waycrystal', 'Kirin Tor Translocation Network', 'Interact', 80, 80, 35, 1, 1, 768, 10, 2, 100, 'npc_custom_waystone');
INSERT INTO `creature_template_locale` (`entry`, `locale`, `Name`, `Title`) VALUES
(9100001, 'ruRU', 'Путевой кристалл', 'Сеть транслокации Кирин-Тора');
INSERT INTO `creature_template_model` (`CreatureID`, `Idx`, `CreatureDisplayID`, `DisplayScale`, `Probability`) VALUES
(9100001, 0, 17856, 1.0, 1);
INSERT INTO `creature_template_movement` (`CreatureId`, `Ground`, `Swim`, `Flight`, `Rooted`) VALUES
(9100001, 0, 0, 1, 1);
INSERT INTO `npc_text` (`ID`, `text0_0`, `Probability0`) VALUES
(9100001, 'The crystal hums with the arcane power of the Kirin Tor. A traveller who has touched it may translocate to any crystal of the network they are attuned to.', 1);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`) VALUES
(9100001, 'ruRU', 'Кристалл гудит тайной магией Кирин-Тора. Путник, коснувшийся его, может перенестись к любому кристаллу сети, на который он уже настроен.');
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES
(44080, 'spell_custom_translocation');
